import{_ as t,c as a,o as s,a2 as n}from"./chunks/framework.PGES7OoM.js";const d=JSON.parse(`{"title":"Swap assets privately","description":"","frontmatter":{"rawMarkdown":"# Swap assets privately\\n\\nCurvy's built-in swap exchanges assets inside your private balance. Open **Swap** from the app's main navigation.\\n\\nThe swap UI is made to feel familiar to users of the popular DEXs:\\n\\n1. Under **You pay**, choose the asset and enter the amount. You can also enter the amount in dollars.\\n2. Choose the asset you want to receive. The reverse button flips the two sides.\\n3. An indicative rate is shown while you type; the exact amounts are calculated in the review.\\n4. Choose **Review swap**.\\n\\nThe review shows a detailed breakdown of the swap, including the rate and the associated fees.\\nRates can move while you are reviewing, so if the quote expires, check the updated amount before confirming.\\n\\nAfter confirming, the swap opens its execution page. Keep it open until the swap finishes; you can follow the\\nexecution of the swap, as well as the shielding of the resulting swapped assets. The new assets appear in your Curvy balance after settlement,\\nand the swap is listed under **Activity**, including recovery options if it was interrupted.\\n","rawMarkdownPath":"/_raw/for-users/swap-assets-privately.md","rawMarkdownTitle":"Swap assets privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/swap-assets-privately.md"},"headers":[],"relativePath":"for-users/swap-assets-privately.md","filePath":"for-users/swap-assets-privately.md","lastUpdated":1791449043000}`),i={name:"for-users/swap-assets-privately.md"};function o(r,e,p,l,h,w){return s(),a("div",null,[...e[0]||(e[0]=[n("",6)])])}const c=t(i,[["render",o]]);export{d as __pageData,c as default};
